// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

contract MarketRegistry {

    enum MarketStatus {
        Open,
        Closed,
        Resolving,
        Resolved,
        Cancelled
    }

    struct Market {
        uint256 id;

        address creator;

        string slug;

        string question;

        string description;

        string category;

        string[] outcomes;

        uint256 endTime;

        string resolutionSource;

        string resolutionRule;

        uint256 createdAt;

        MarketStatus status;
    }
   uint256 public nextMarketId;

mapping(uint256 => Market) public markets;

mapping(string => bool) public slugExists;

event MarketCreated(
    uint256 indexed marketId,
    address indexed creator,
    string slug
);
function createMarket(
    string memory slug,
    string memory question,
    string memory description,
    string memory category,
    string[] memory outcomes,
    uint256 endTime,
    string memory resolutionSource,
    string memory resolutionRule
) public {
    require(bytes(slug).length > 0, "Slug is required");

require(bytes(question).length > 0, "Question is required");

require(outcomes.length >= 2, "At least two outcomes required");

require(endTime > block.timestamp, "End time must be in the future");

require(!slugExists[slug], "Slug already exists");

uint256 marketId = nextMarketId;

markets[marketId] = Market({
    id: marketId,
    creator: msg.sender,
    slug: slug,
    question: question,
    description: description,
    category: category,
    outcomes: outcomes,
    endTime: endTime,
    resolutionSource: resolutionSource,
    resolutionRule: resolutionRule,
    createdAt: block.timestamp,
    status: MarketStatus.Open
});

slugExists[slug] = true;

nextMarketId++;

emit MarketCreated(
    marketId,
    msg.sender,
    slug
);

}
function getMarket(
    uint256 marketId
) public view returns (Market memory) {
    return markets[marketId];
}

}

